package ansifilter

import (
	"fmt"
	"os"
	"strconv"
)

// svgGenerator emits an SVG document.
type svgGenerator struct{ *Generator }

func newSVGGenerator() *svgGenerator {
	g := newGenerator(SVG)
	s := &svgGenerator{g}
	g.f = s
	g.spacer = "&#160;"
	g.newLineTag = "\n"
	g.styleCommentOpen = "/*"
	g.styleCommentClose = "*/"
	return s
}

func (s *svgGenerator) openTag() string {
	attrName := "style"
	var fmtStream string

	if s.applyDynStyles {
		attrName = "class"
		fmtStream = s.dynStyleClass()
	} else {
		// SVG paints text with fill and carries no background color.
		fmtStream = s.inlineStyle("fill", false)
	}

	s.tagIsOpen = len(fmtStream) > 0
	if s.tagIsOpen {
		return `<tspan ` + attrName + `="` + fmtStream + `">`
	}
	return ""
}

func (s *svgGenerator) closeTag() string {
	if s.tagIsOpen {
		s.tagIsOpen = false
		return "</tspan>"
	}
	return ""
}

func (s *svgGenerator) header() string {
	h := `<?xml version="1.0"`
	if s.encodingDefined() {
		h += ` encoding="` + s.encoding + `"`
	}
	h += "?>\n"
	if s.styleSheetPath != "" {
		h += `<?xml-stylesheet type="text/css" href="` + s.styleSheetPath + `"?>` + "\n"
	}
	h += "<!DOCTYPE svg PUBLIC \"-//W3C//DTD SVG 1.2//EN\" " +
		"\"http://www.w3.org/Graphics/SVG/1.2/DTD/svg12.dtd\">\n"
	h += `<svg xmlns="http://www.w3.org/2000/svg" version="1.2" ` +
		`baseProfile="full" xml:space="preserve"`
	if s.width != "" {
		h += ` width="` + s.width + `"`
	}
	if s.height != "" {
		h += ` height="` + s.height + `"`
	}
	h += ">\n<desc>" + s.docTitle + "</desc>\n"

	if s.styleSheetPath == "" {
		h += "<defs><style type=\"text/css\">\n" + "<![CDATA[\n"
		h += "rect { fill:#ffffff; } \n"
		h += "g { font-size: " + s.fontSize
		h += "; font-family: " + s.font + "; white-space: pre; }\n"
		h += "]]>\n" + "</style></defs>"
	}
	return h
}

func (s *svgGenerator) body() {
	// The rect supplies the background color.
	s.write("<g>\n<rect x=\"0\" y=\"0\" width=\"100%\" height=\"100%\"/>")
	fontSizeSVG := 10
	if v := atoiC(s.fontSize); v != 0 {
		fontSizeSVG = v
	}
	s.write("\n<text x=\"10\" y=\"" + strconv.Itoa(fontSizeSVG*2) + "\">")
	s.processInput()
	s.write("</text>\n</g>\n")
}

func (s *svgGenerator) footer() string {
	return "</svg>\n" +
		"<!-- SVG generated by ansifilter " + Version + ", " + URL + " -->\n"
}

func (s *svgGenerator) lineNum() {
	fontSizeSVG := 10
	if v := atoiC(s.fontSize); v != 0 {
		fontSizeSVG = v
	}
	if s.showLineNumbers {
		if s.numberCurrentLine {
			s.write("</text>\n<text x=\"10\" y=\"" + strconv.Itoa(s.lineNumber*fontSizeSVG*2) + "\">")
			s.write(fmt.Sprintf("%5d", s.lineNumber))
		}
		s.write(" ")
	} else {
		s.write("</text>\n<text x=\"10\" y=\"" + strconv.Itoa(s.lineNumber*fontSizeSVG*2) + "\">")
	}
}

func (s *svgGenerator) maskChar(c byte) string {
	switch c {
	case ' ':
		return s.spacer
	case '<':
		return "&lt;"
	case '>':
		return "&gt;"
	case '&':
		return "&amp;"
	case '"':
		return "&quot;"
	default:
		return chr(c)
	}
}

// printDynamicStyleFile writes the stylesheet derived from the styles seen in
// the document. An existing file is never overwritten.
func (s *svgGenerator) printDynamicStyleFile(outPath string) error {
	if _, err := os.Stat(outPath); err == nil {
		return nil
	}
	out := "/* CSS generated by ansifilter - styles derived from document formatting\n   Ansifilter will not overwrite this file\n*/\n"
	out += "rect { fill:#ffffff; }\n"
	out += "g { font-size: " + s.fontSize
	out += "; font-family: " + s.font + "; white-space: pre; }\n"
	for i, sInfo := range s.documentStyles {
		out += "tspan.af_" + strconv.Itoa(i+1) + " {"
		out += dynStyleBody(sInfo, "fill", false)
		out += "}\n"
	}
	return os.WriteFile(outPath, []byte(out), 0o644) //nolint:gosec
}
